-- 001_initial: schema v1 (ARCHITECTURE §5).
--
-- Conventions
--   ids          TEXT, UUID v7 (time-sortable), generated by the app.
--   moments      TEXT, UTC ISO-8601 with milliseconds: 2026-11-05T08:30:00.000Z
--   calendar     TEXT, local date 'YYYY-MM-DD' / local time 'HH:MM', never converted.
--   booleans     INTEGER 0/1.
--   JSON         TEXT, checked with json_valid().
--   soft delete  deleted_at (NULL = alive). Main tables also carry created_at / updated_at.
-- Tables are STRICT: SQLite rejects values of the wrong type instead of storing them silently.
-- This script runs inside the migration transaction; it must not contain BEGIN/COMMIT.

-- Taxonomies ------------------------------------------------------------------------------------

CREATE TABLE task_statuses (
    id          TEXT    NOT NULL PRIMARY KEY,
    name        TEXT    NOT NULL,
    kind        TEXT    NOT NULL CHECK (kind IN ('todo', 'active', 'waiting', 'blocked', 'done', 'cancelled')),
    color       TEXT,
    sort        INTEGER NOT NULL DEFAULT 0,
    is_system   INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0, 1)),
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
) STRICT;

-- One system status per kind; names are display defaults (localized in the UI by id).
INSERT INTO task_statuses (id, name, kind, color, sort, is_system) VALUES
    ('status-todo',      'De făcut',     'todo',      NULL, 0, 1),
    ('status-active',    'În lucru',     'active',    NULL, 1, 1),
    ('status-waiting',   'În așteptare', 'waiting',   NULL, 2, 1),
    ('status-blocked',   'Blocat',       'blocked',   NULL, 3, 1),
    ('status-done',      'Finalizat',    'done',      NULL, 4, 1),
    ('status-cancelled', 'Anulat',       'cancelled', NULL, 5, 1);

CREATE TABLE categories (
    id          TEXT    NOT NULL PRIMARY KEY,
    name        TEXT    NOT NULL,
    color       TEXT,
    icon        TEXT,
    sort        INTEGER NOT NULL DEFAULT 0,
    is_demo     INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
) STRICT;

CREATE TABLE projects (
    id          TEXT    NOT NULL PRIMARY KEY,
    name        TEXT    NOT NULL,
    description TEXT,
    color       TEXT,
    due_date    TEXT    CHECK (due_date IS NULL OR date(due_date) IS due_date),
    sort        INTEGER NOT NULL DEFAULT 0,
    archived_at TEXT,
    is_demo     INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
) STRICT;

CREATE TABLE tags (
    id          TEXT    NOT NULL PRIMARY KEY,
    name        TEXT    NOT NULL,
    color       TEXT,
    is_demo     INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
) STRICT;

-- "Urgent" and "urgent" are the same tag; a deleted tag frees its name.
CREATE UNIQUE INDEX ux_tags_name ON tags (name COLLATE NOCASE) WHERE deleted_at IS NULL;

-- Recurrence and workflows (referenced by tasks) ------------------------------------------------

CREATE TABLE recurrence_rules (
    id              TEXT NOT NULL PRIMARY KEY,
    rrule           TEXT NOT NULL,
    tz_id           TEXT NOT NULL,
    anchor          TEXT NOT NULL DEFAULT 'due' CHECK (anchor IN ('due', 'completion')),
    next_occurrence TEXT,
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at      TEXT
) STRICT;

CREATE TABLE workflow_templates (
    id          TEXT    NOT NULL PRIMARY KEY,
    name        TEXT    NOT NULL,
    description TEXT,
    is_system   INTEGER NOT NULL DEFAULT 0 CHECK (is_system IN (0, 1)),
    is_demo     INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
) STRICT;

CREATE TABLE workflow_stages (
    id              TEXT    NOT NULL PRIMARY KEY,
    template_id     TEXT    NOT NULL REFERENCES workflow_templates (id) ON DELETE CASCADE,
    name            TEXT    NOT NULL,
    description     TEXT,
    sort            INTEGER NOT NULL DEFAULT 0,
    -- Due offset in business days from the instance start (e.g. month-end close: "BD+3").
    due_offset_bd   INTEGER,
    created_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at      TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at      TEXT
) STRICT;

CREATE TABLE stage_checklist_items (
    id          TEXT    NOT NULL PRIMARY KEY,
    stage_id    TEXT    NOT NULL REFERENCES workflow_stages (id) ON DELETE CASCADE,
    text        TEXT    NOT NULL,
    sort        INTEGER NOT NULL DEFAULT 0
) STRICT;

CREATE TABLE workflow_instances (
    id          TEXT NOT NULL PRIMARY KEY,
    template_id TEXT REFERENCES workflow_templates (id) ON DELETE SET NULL,
    title       TEXT NOT NULL,
    -- Period the run belongs to, e.g. '2026-11' for a month-end close.
    period      TEXT,
    status      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'completed', 'cancelled')),
    is_demo     INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
) STRICT;

-- Tasks ---------------------------------------------------------------------------------------

CREATE TABLE tasks (
    id                   TEXT    NOT NULL PRIMARY KEY,
    title                TEXT    NOT NULL CHECK (length(trim(title)) > 0),
    description          TEXT,
    notes                TEXT,
    status_id            TEXT    NOT NULL REFERENCES task_statuses (id),
    priority             INTEGER NOT NULL DEFAULT 0 CHECK (priority BETWEEN 0 AND 4),
    category_id          TEXT    REFERENCES categories (id) ON DELETE SET NULL,
    project_id           TEXT    REFERENCES projects (id) ON DELETE SET NULL,
    parent_task_id       TEXT    REFERENCES tasks (id) ON DELETE CASCADE,
    due_date             TEXT    CHECK (due_date IS NULL OR date(due_date) IS due_date),
    due_time             TEXT    CHECK (due_time IS NULL OR (due_date IS NOT NULL AND strftime('%H:%M', '2000-01-01 ' || due_time) IS due_time)),
    start_date           TEXT    CHECK (start_date IS NULL OR date(start_date) IS start_date),
    estimate_min         INTEGER CHECK (estimate_min IS NULL OR estimate_min >= 0),
    actual_min           INTEGER CHECK (actual_min IS NULL OR actual_min >= 0),
    external_ref         TEXT,
    external_url         TEXT,
    requester            TEXT,
    responsible          TEXT,
    recurrence_id        TEXT    REFERENCES recurrence_rules (id) ON DELETE SET NULL,
    workflow_instance_id TEXT    REFERENCES workflow_instances (id) ON DELETE SET NULL,
    workflow_stage_id    TEXT    REFERENCES workflow_stages (id) ON DELETE SET NULL,
    is_pinned            INTEGER NOT NULL DEFAULT 0 CHECK (is_pinned IN (0, 1)),
    sort_order           REAL    NOT NULL DEFAULT 0,
    completed_at         TEXT,
    archived_at          TEXT,
    is_demo              INTEGER NOT NULL DEFAULT 0 CHECK (is_demo IN (0, 1)),
    created_at           TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at           TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at           TEXT,
    CHECK (parent_task_id IS NULL OR parent_task_id <> id)
) STRICT;

CREATE INDEX ix_tasks_due ON tasks (due_date, due_time) WHERE deleted_at IS NULL AND archived_at IS NULL;
CREATE INDEX ix_tasks_status ON tasks (status_id) WHERE deleted_at IS NULL;
CREATE INDEX ix_tasks_project ON tasks (project_id) WHERE project_id IS NOT NULL;
CREATE INDEX ix_tasks_category ON tasks (category_id) WHERE category_id IS NOT NULL;
CREATE INDEX ix_tasks_parent ON tasks (parent_task_id) WHERE parent_task_id IS NOT NULL;
CREATE INDEX ix_tasks_workflow ON tasks (workflow_instance_id) WHERE workflow_instance_id IS NOT NULL;
CREATE INDEX ix_tasks_completed ON tasks (completed_at) WHERE completed_at IS NOT NULL;
CREATE INDEX ix_tasks_demo ON tasks (is_demo) WHERE is_demo = 1;

CREATE TABLE task_tags (
    task_id TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    tag_id  TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
    PRIMARY KEY (task_id, tag_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX ix_task_tags_tag ON task_tags (tag_id);

CREATE TABLE checklist_items (
    id          TEXT    NOT NULL PRIMARY KEY,
    task_id     TEXT    NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    text        TEXT    NOT NULL,
    is_done     INTEGER NOT NULL DEFAULT 0 CHECK (is_done IN (0, 1)),
    sort        REAL    NOT NULL DEFAULT 0,
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE INDEX ix_checklist_task ON checklist_items (task_id, sort);

-- Dependencies. Cycle detection for 'blocks' lives in the domain (M19); the table only refuses self-links.
CREATE TABLE task_links (
    from_id     TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    to_id       TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    kind        TEXT NOT NULL CHECK (kind IN ('related', 'blocks')),
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    PRIMARY KEY (from_id, to_id, kind),
    CHECK (from_id <> to_id)
) STRICT, WITHOUT ROWID;

CREATE INDEX ix_task_links_to ON task_links (to_id);

CREATE TABLE custom_fields (
    id          TEXT    NOT NULL PRIMARY KEY,
    name        TEXT    NOT NULL,
    kind        TEXT    NOT NULL CHECK (kind IN ('text', 'number', 'date', 'choice', 'bool')),
    options     TEXT    CHECK (options IS NULL OR json_valid(options)),
    sort        INTEGER NOT NULL DEFAULT 0,
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
) STRICT;

CREATE TABLE task_field_values (
    task_id  TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    field_id TEXT NOT NULL REFERENCES custom_fields (id) ON DELETE CASCADE,
    value    TEXT,
    PRIMARY KEY (task_id, field_id)
) STRICT, WITHOUT ROWID;

-- Reminders and notifications (ARCHITECTURE §6) ----------------------------------------------------

CREATE TABLE reminders (
    id                  TEXT    NOT NULL PRIMARY KEY,
    task_id             TEXT    NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    kind                TEXT    NOT NULL CHECK (kind IN ('absolute', 'relative_to_due', 'follow_up', 'overdue')),
    offset_min          INTEGER,
    at_local            TEXT,
    tz_id               TEXT,
    repeat_rule         TEXT,
    sound               TEXT,
    silent              INTEGER NOT NULL DEFAULT 0 CHECK (silent IN (0, 1)),
    respect_quiet_hours INTEGER NOT NULL DEFAULT 1 CHECK (respect_quiet_hours IN (0, 1)),
    created_at          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at          TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at          TEXT,
    CHECK (kind <> 'absolute' OR at_local IS NOT NULL),
    CHECK (kind <> 'relative_to_due' OR offset_min IS NOT NULL)
) STRICT;

CREATE INDEX ix_reminders_task ON reminders (task_id);

-- id is deterministic (reminder id + due moment), so the same occurrence can never be created twice.
CREATE TABLE reminder_occurrences (
    id              TEXT NOT NULL PRIMARY KEY,
    reminder_id     TEXT NOT NULL REFERENCES reminders (id) ON DELETE CASCADE,
    due_utc         TEXT NOT NULL,
    state           TEXT NOT NULL DEFAULT 'pending'
                    CHECK (state IN ('pending', 'deferred', 'delivered', 'delivered_by_os', 'snoozed', 'acted', 'missed', 'cancelled')),
    delivered_via   TEXT CHECK (delivered_via IS NULL OR delivered_via IN ('toast', 'scheduled_toast', 'in_app', 'summary')),
    delivered_at    TEXT,
    acted_at        TEXT,
    action          TEXT CHECK (action IS NULL OR action IN ('done', 'dismissed', 'opened', 'snoozed')),
    snoozed_until   TEXT,
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (reminder_id, due_utc)
) STRICT;

-- Reconciliation reads "pending/deferred with due_utc <= now" (§6.4).
CREATE INDEX ix_occurrences_open ON reminder_occurrences (due_utc) WHERE state IN ('pending', 'deferred');

CREATE TABLE notifications (
    id              TEXT NOT NULL PRIMARY KEY,
    occurrence_id   TEXT REFERENCES reminder_occurrences (id) ON DELETE SET NULL,
    type            TEXT NOT NULL,
    title           TEXT NOT NULL,
    body            TEXT,
    created_at      TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    read_at         TEXT
) STRICT;

CREATE INDEX ix_notifications_unread ON notifications (created_at) WHERE read_at IS NULL;

-- Follow-ups ---------------------------------------------------------------------------------------

CREATE TABLE follow_ups (
    id                TEXT    NOT NULL PRIMARY KEY,
    task_id           TEXT    NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    contact_name      TEXT,
    requested_at      TEXT,
    expected_by       TEXT,
    next_follow_up    TEXT,
    escalate_after_bd INTEGER CHECK (escalate_after_bd IS NULL OR escalate_after_bd >= 0),
    closed_at         TEXT,
    created_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at        TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at        TEXT
) STRICT;

CREATE INDEX ix_follow_ups_task ON follow_ups (task_id);
CREATE INDEX ix_follow_ups_next ON follow_ups (next_follow_up) WHERE closed_at IS NULL AND deleted_at IS NULL;

CREATE TABLE follow_up_events (
    id           TEXT NOT NULL PRIMARY KEY,
    follow_up_id TEXT NOT NULL REFERENCES follow_ups (id) ON DELETE CASCADE,
    kind         TEXT NOT NULL CHECK (kind IN ('sent', 'received', 'escalated', 'note')),
    at           TEXT NOT NULL,
    note         TEXT
) STRICT;

CREATE INDEX ix_follow_up_events ON follow_up_events (follow_up_id, at);

-- Automation -----------------------------------------------------------------------------------------

CREATE TABLE automation_rules (
    id          TEXT    NOT NULL PRIMARY KEY,
    name        TEXT    NOT NULL,
    enabled     INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    trigger     TEXT    NOT NULL CHECK (json_valid(trigger)),
    conditions  TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(conditions)),
    actions     TEXT    NOT NULL CHECK (json_valid(actions)),
    priority    INTEGER NOT NULL DEFAULT 0,
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deleted_at  TEXT
) STRICT;

CREATE TABLE automation_runs (
    id               TEXT NOT NULL PRIMARY KEY,
    rule_id          TEXT NOT NULL REFERENCES automation_rules (id) ON DELETE CASCADE,
    trigger_event_id TEXT,
    entity_id        TEXT,
    -- Same rule + same event + same entity runs at most once, even after a crash and replay.
    idempotency_key  TEXT NOT NULL UNIQUE,
    result           TEXT NOT NULL CHECK (result IN ('applied', 'skipped', 'failed')),
    changes          TEXT CHECK (changes IS NULL OR json_valid(changes)),
    at               TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    undone_at        TEXT
) STRICT;

CREATE INDEX ix_automation_runs_rule ON automation_runs (rule_id, at);

-- Time ---------------------------------------------------------------------------------------------

CREATE TABLE time_entries (
    id          TEXT NOT NULL PRIMARY KEY,
    task_id     TEXT NOT NULL REFERENCES tasks (id) ON DELETE CASCADE,
    started_at  TEXT NOT NULL,
    ended_at    TEXT,
    source      TEXT NOT NULL CHECK (source IN ('timer', 'manual')),
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    CHECK (ended_at IS NULL OR ended_at >= started_at)
) STRICT;

CREATE INDEX ix_time_entries_task ON time_entries (task_id, started_at);

CREATE TABLE calendar_blocks (
    id            TEXT    NOT NULL PRIMARY KEY,
    task_id       TEXT    REFERENCES tasks (id) ON DELETE SET NULL,
    title         TEXT,
    start_utc     TEXT    NOT NULL,
    end_utc       TEXT    NOT NULL,
    is_suggestion INTEGER NOT NULL DEFAULT 0 CHECK (is_suggestion IN (0, 1)),
    created_at    TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    CHECK (end_utc > start_utc)
) STRICT;

CREATE INDEX ix_calendar_blocks_start ON calendar_blocks (start_utc);

CREATE TABLE holidays (
    calendar_id TEXT NOT NULL,
    date        TEXT NOT NULL CHECK (date(date) IS date),
    name        TEXT NOT NULL,
    PRIMARY KEY (calendar_id, date)
) STRICT, WITHOUT ROWID;

-- UI state and settings --------------------------------------------------------------------------------

CREATE TABLE saved_filters (
    id          TEXT    NOT NULL PRIMARY KEY,
    name        TEXT    NOT NULL,
    definition  TEXT    NOT NULL CHECK (json_valid(definition)),
    sort        INTEGER NOT NULL DEFAULT 0,
    created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE dashboard_layouts (
    id          TEXT NOT NULL PRIMARY KEY,
    name        TEXT NOT NULL,
    layout      TEXT NOT NULL CHECK (json_valid(layout)),
    created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT;

CREATE TABLE settings (
    key         TEXT NOT NULL PRIMARY KEY,
    value       TEXT NOT NULL CHECK (json_valid(value)),
    updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
) STRICT, WITHOUT ROWID;

-- Audit / undo: before and after are JSON snapshots of the changed entity.
CREATE TABLE activity_log (
    id          TEXT NOT NULL PRIMARY KEY,
    at          TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    actor       TEXT NOT NULL CHECK (actor IN ('user', 'system') OR actor LIKE 'automation:%'),
    command     TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id   TEXT NOT NULL,
    before      TEXT CHECK (before IS NULL OR json_valid(before)),
    after       TEXT CHECK (after IS NULL OR json_valid(after))
) STRICT;

CREATE INDEX ix_activity_entity ON activity_log (entity_type, entity_id, at);
CREATE INDEX ix_activity_at ON activity_log (at);

-- Full-text search (FTS5) ------------------------------------------------------------------------------
-- One row per task, kept in sync by triggers. remove_diacritics 2 makes "sedinta" match "Ședință"
-- (both comma and cedilla forms). Trashed and archived tasks stay indexed: queries join tasks to filter.

CREATE VIRTUAL TABLE search_fts USING fts5 (
    task_id UNINDEXED,
    title,
    description,
    notes,
    tags,
    refs,
    tokenize = 'unicode61 remove_diacritics 2'
);

CREATE TRIGGER tr_tasks_fts_insert AFTER INSERT ON tasks
BEGIN
    INSERT INTO search_fts (task_id, title, description, notes, tags, refs)
    VALUES (new.id, new.title, coalesce(new.description, ''), coalesce(new.notes, ''), '',
            trim(coalesce(new.external_ref, '') || ' ' || coalesce(new.requester, '') || ' ' || coalesce(new.responsible, '')));
END;

CREATE TRIGGER tr_tasks_fts_update AFTER UPDATE OF title, description, notes, external_ref, requester, responsible ON tasks
BEGIN
    UPDATE search_fts
    SET title = new.title,
        description = coalesce(new.description, ''),
        notes = coalesce(new.notes, ''),
        refs = trim(coalesce(new.external_ref, '') || ' ' || coalesce(new.requester, '') || ' ' || coalesce(new.responsible, ''))
    WHERE task_id = new.id;
END;

CREATE TRIGGER tr_tasks_fts_delete AFTER DELETE ON tasks
BEGIN
    DELETE FROM search_fts WHERE task_id = old.id;
END;

CREATE TRIGGER tr_task_tags_fts_insert AFTER INSERT ON task_tags
BEGIN
    UPDATE search_fts
    SET tags = (SELECT coalesce(group_concat(t.name, ' '), '') FROM task_tags tt JOIN tags t ON t.id = tt.tag_id
                WHERE tt.task_id = new.task_id AND t.deleted_at IS NULL)
    WHERE task_id = new.task_id;
END;

CREATE TRIGGER tr_task_tags_fts_delete AFTER DELETE ON task_tags
BEGIN
    UPDATE search_fts
    SET tags = (SELECT coalesce(group_concat(t.name, ' '), '') FROM task_tags tt JOIN tags t ON t.id = tt.tag_id
                WHERE tt.task_id = old.task_id AND t.deleted_at IS NULL)
    WHERE task_id = old.task_id;
END;

CREATE TRIGGER tr_tags_fts_update AFTER UPDATE OF name, deleted_at ON tags
BEGIN
    UPDATE search_fts
    SET tags = (SELECT coalesce(group_concat(t.name, ' '), '') FROM task_tags tt JOIN tags t ON t.id = tt.tag_id
                WHERE tt.task_id = search_fts.task_id AND t.deleted_at IS NULL)
    WHERE task_id IN (SELECT task_id FROM task_tags WHERE tag_id = new.id);
END;
